   325	+package com.papaya.claims.claim.domain.persistence;
   326	+
   327	+import com.fasterxml.jackson.core.JsonProcessingException;
   328	+import com.fasterxml.jackson.core.type.TypeReference;
   329	+import com.fasterxml.jackson.databind.ObjectMapper;
   330	+import com.papaya.claims.claim.domain.*;
   331	+import java.util.Map;
   332	+
   333	+final class PersistenceMapping {
   334	+    private static final TypeReference<Map<String,Object>> MAP = new TypeReference<>() {};
   335	+    private PersistenceMapping() {}
   336	+    static String json(ObjectMapper mapper, Object value) {
   337	+        try { return mapper.writeValueAsString(value); }
   338	+        catch (JsonProcessingException e) { throw new IllegalArgumentException("Could not encode persistence JSON", e); }
   339	+    }
   340	+    static Map<String,Object> map(ObjectMapper mapper, String value) {
   341	+        try { return mapper.readValue(value, MAP); }
   342	+        catch (JsonProcessingException e) { throw new IllegalStateException("Could not decode persisted JSON", e); }
   343	+    }
   344	+    static ClaimAggregate aggregate(ObjectMapper mapper, ClaimRow r) {
   345	+        Claim c = new Claim(r.id, r.memberId, r.state, r.policyLimit, r.currency, r.version,
   346	+                new ClaimFacts(map(mapper, r.factsJson)), r.createdAt, r.updatedAt);
   347	+        return new ClaimAggregate(c, new ClaimWorkflowData(r.informationRequests, r.lastInformationRequestedAt,
   348	+                r.lastInformationReceivedAt, r.assessmentStartedAt, r.rejectedAt, r.memberAcknowledgedRejectionAt));
   349	+    }
   350	+    static ClaimRow row(ObjectMapper mapper, ClaimAggregate a) {
   351	+        Claim c = a.claim(); ClaimWorkflowData w = a.workflow(); ClaimRow r = new ClaimRow();
   352	+        r.id=c.id(); r.memberId=c.memberId(); r.state=c.state(); r.policyLimit=c.policyLimit(); r.currency=c.currency();
   353	+        r.version=c.version(); r.factsJson=json(mapper,c.facts().values()); r.informationRequests=w.informationRequests();
   354	+        r.lastInformationRequestedAt=w.lastInformationRequestedAt(); r.lastInformationReceivedAt=w.lastInformationReceivedAt();
   355	+        r.assessmentStartedAt=w.assessmentStartedAt(); r.rejectedAt=w.rejectedAt();
   356	+        r.memberAcknowledgedRejectionAt=w.memberAcknowledgedRejectionAt(); r.createdAt=c.createdAt(); r.updatedAt=c.updatedAt(); return r;
   357	+    }
   358	+}
